export const formatDateForAPIFromDate = (date: Date): string => {
    if (Number.isNaN(date.getTime())) {
        console.warn('formatDateForAPIFromDate failed to parse date', date);
        return '';
    }

    const day: string = zeroPad2(date.getDate());
    const month: string = zeroPad2(date.getMonth() + 1);
    const year: number = date.getFullYear();
    const formattedDate: string = `${day}-${month}-${year}`;

    return formattedDate;
};

export const formatDateForAPI = (dateInput: string): string => {
    if (!dateInput) {
        console.warn('formatDateForAPI called with empty dateInput');
        return '';
    }

    const date = new Date(dateInput);
    return formatDateForAPIFromDate(date);
};

const formatYMD = (date: Date): string =>
    `${date.getFullYear()}-${zeroPad2(date.getMonth() + 1)}-${zeroPad2(date.getDate())}`;

export const getThisMonthRange = (): { start: string; end: string } => {
    const now = new Date();
    const start = new Date(now.getFullYear(), now.getMonth(), 1);
    const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);

    return {
        start: formatYMD(start),
        end: formatYMD(end),
    };
};

export const getTodayRange = (): { start: string; end: string } => {
    const today = new Date();
    const todayFormatted = formatYMD(today);

    return {
        start: todayFormatted,
        end: todayFormatted,
    };
};

export const normalizeToYMD = (d: any): string | null => {
    if (!d) return null;
    if (typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d)) return d;

    const dt = new Date(d);
    if (Number.isNaN(dt.getTime())) return null;

    return formatYMD(dt);
};
